const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const taiwan = ee.Geometry.Polygon([
    [[119.0, 21.5], [123.0, 21.5], [123.0, 26.0], [119.0, 26.0], [119.0, 21.5]]
  ]);

  const period1_start = '2020-02-10';
  const period1_end = '2020-02-25';
  const period2_start = '2020-04-20';
  const period2_end = '2020-05-12';

  // 2. Data Acquisition - Sentinel-5P NO2 data
  const no2_col1 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(period1_start, period1_end)
    .filterBounds(taiwan)
    .select('tropospheric_NO2_column_number_density');

  const no2_col2 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(period2_start, period2_end)
    .filterBounds(taiwan)
    .select('tropospheric_NO2_column_number_density');

  // Check collection sizes
  const size1 = no2_col1.size().getInfo();
  const size2 = no2_col2.size().getInfo();

  console.log(`Period 1 (Feb 10-25): ${size1} images`);
  console.log(`Period 2 (Apr 20-May 12): ${size2} images`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Create mean composites for each period
  const mean_no2_1 = no2_col1.mean();
  const mean_no2_2 = no2_col2.mean();

  // Calculate mean NO2 values and pixel counts
  const stats1 = mean_no2_1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: taiwan,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2 = mean_no2_2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: taiwan,
    scale: 1000,
    maxPixels: 1e9
  });

  const mean1 = stats1.get('tropospheric_NO2_column_number_density_mean').getInfo();
  const count1 = stats1.get('tropospheric_NO2_column_number_density_count').getInfo();
  const mean2 = stats2.get('tropospheric_NO2_column_number_density_mean').getInfo();
  const count2 = stats2.get('tropospheric_NO2_column_number_density_count').getInfo();

  console.log(`Period 1: Mean NO2 = ${mean1 ? mean1.toFixed(6) : 'null'}, Pixels = ${count1}`);
  console.log(`Period 2: Mean NO2 = ${mean2 ? mean2.toFixed(6) : 'null'}, Pixels = ${count2}`);

  // Check for valid pixels
  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (mean1 === null || mean2 === null || !isFinite(mean1) || !isFinite(mean2)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Validate reasonable NO2 range (mol/m²)
  if (mean1 < 0 || mean1 > 0.01 || mean2 < 0 || mean2 > 0.01) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Determine if NO2 increased
  const increased = mean2 > mean1;
  console.log(`Change: ${((mean2 - mean1) / mean1 * 100).toFixed(1)}%`);

  if (increased) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
